PaddingMode::PaddingMode() : tag_(Tag::kConstant) {
  data_.constant = new ConstantPaddingPtr;
}

PaddingMode::~PaddingMode() {
  DestroyActive();
}


void PaddingMode::set_constant(
    ConstantPaddingPtr constant) {
  if (tag_ == Tag::kConstant) {
    *(data_.constant) = std::move(constant);
  } else {
    DestroyActive();
    tag_ = Tag::kConstant;
    data_.constant = new ConstantPaddingPtr(
        std::move(constant));
  }
}
void PaddingMode::set_edge(
    EdgePaddingPtr edge) {
  if (tag_ == Tag::kEdge) {
    *(data_.edge) = std::move(edge);
  } else {
    DestroyActive();
    tag_ = Tag::kEdge;
    data_.edge = new EdgePaddingPtr(
        std::move(edge));
  }
}
void PaddingMode::set_reflection(
    ReflectionPaddingPtr reflection) {
  if (tag_ == Tag::kReflection) {
    *(data_.reflection) = std::move(reflection);
  } else {
    DestroyActive();
    tag_ = Tag::kReflection;
    data_.reflection = new ReflectionPaddingPtr(
        std::move(reflection));
  }
}
void PaddingMode::set_symmetric(
    SymmetricPaddingPtr symmetric) {
  if (tag_ == Tag::kSymmetric) {
    *(data_.symmetric) = std::move(symmetric);
  } else {
    DestroyActive();
    tag_ = Tag::kSymmetric;
    data_.symmetric = new SymmetricPaddingPtr(
        std::move(symmetric));
  }
}

void PaddingMode::DestroyActive() {
  switch (tag_) {

    case Tag::kConstant:

      delete data_.constant;
      break;
    case Tag::kEdge:

      delete data_.edge;
      break;
    case Tag::kReflection:

      delete data_.reflection;
      break;
    case Tag::kSymmetric:

      delete data_.symmetric;
      break;
  }
}
size_t PaddingMode::Hash(size_t seed) const {
  seed = mojo::internal::HashCombine(seed, static_cast<uint32_t>(tag_));
  switch (tag_) {

    case Tag::kConstant:
      return mojo::internal::WTFHash(seed, data_.constant);
    case Tag::kEdge:
      return mojo::internal::WTFHash(seed, data_.edge);
    case Tag::kReflection:
      return mojo::internal::WTFHash(seed, data_.reflection);
    case Tag::kSymmetric:
      return mojo::internal::WTFHash(seed, data_.symmetric);
    default:
      NOTREACHED();
      return seed;
  }
}

bool PaddingMode::Validate(
    const void* data,
    mojo::internal::ValidationContext* validation_context) {
  return Data_::Validate(data, validation_context, false);
}
